// FolderFilter provides filtering for Folder queries
type FolderFilter struct {
	Id                *UUIDFilter
	Name              *StringFilter
	Owner             *UUIDFilter
	CreatedAt         *DateTimeFilter
	CreatedBy         *UUIDFilter
	Audience          *StringFilter
	AudienceNamed     *ArrayStringFilter
	AgentAccess       *StringFilter
	EffectiveAudience *ArrayStringFilter
	EffectiveAgents   *StringFilter
	// Documents keeps the rows that some Document row the filter
	// finds points at by its folder (D108, D180): one condition, the key
	// in the foreign keys of those rows.
	Documents *DocumentFilter
	// ReferencedByDocumentFolder filters on the presence or absence of a
	// Document whose folder points at this row.
	ReferencedByDocumentFolder *ReferencedByFilter
	// AllOf keeps the rows every one of its filters finds, beside the
	// filter's other conditions (D99): each filter's conditions are ANDed
	// with them, so two AnyOf groups, each in a filter of its own, must
	// both hold. A filter of no condition adds none, and so does an empty
	// AllOf.
	AllOf []FolderFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []FolderFilter
	// holdsAudienceNamed keeps the rows whose audienceNamed, a list of ids, holds it:
	// a row rule's condition (#735), which FolderHoldingAudienceNamed sets.
	holdsAudienceNamed *types.IdentityUUID
	// holdsEffectiveAudience keeps the rows whose effectiveAudience, a list of ids, holds it:
	// a row rule's condition (#735), which FolderHoldingEffectiveAudience sets.
	holdsEffectiveAudience *types.IdentityUUID
	// scope holds each table a condition through a relation reads to the
	// caller of the operation that reads it (D156, D180); nil outside one.
	scope accessScope
}

// FolderHoldingAudienceNamed is the filter of the Folder rows whose
// audienceNamed, a list of ids, holds id: the condition a row rule names the
// list by (#735), which no request's filter can.
func FolderHoldingAudienceNamed(id types.IdentityUUID) *FolderFilter {
	return &FolderFilter{holdsAudienceNamed: &id}
}

// FolderHoldingEffectiveAudience is the filter of the Folder rows whose
// effectiveAudience, a list of ids, holds id: the condition a row rule names the
// list by (#735), which no request's filter can.
func FolderHoldingEffectiveAudience(id types.IdentityUUID) *FolderFilter {
	return &FolderFilter{holdsEffectiveAudience: &id}
}

// FolderUpdate provides fields that can be updated
type FolderUpdate struct {
	Name                     *string
	Owner                    *types.IdentityUUID
	Audience                 *string
	AudienceNamed            *[]types.IdentityUUID
	AudienceNamedSetNull     bool
	AgentAccess              *string
	EffectiveAudience        *[]types.IdentityUUID
	EffectiveAudienceSetNull bool
	EffectiveAgents          *string
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewFolderSnapshotUpdate maps every mutable field from a complete
// Folder value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewFolderSnapshotUpdate(input *types.Folder) *FolderUpdate {
	update := &FolderUpdate{}
	if input == nil {
		return update
	}
	update.Name = &input.Name
	update.Owner = &input.Owner
	update.Audience = &input.Audience
	if input.AudienceNamed == nil {
		update.AudienceNamedSetNull = true
	} else {
		update.AudienceNamed = &input.AudienceNamed
	}
	update.AgentAccess = &input.AgentAccess
	if input.EffectiveAudience == nil {
		update.EffectiveAudienceSetNull = true
	} else {
		update.EffectiveAudience = &input.EffectiveAudience
	}
	update.EffectiveAgents = &input.EffectiveAgents
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *FolderUpdate) ApplyTo(row *types.Folder) {
	if u == nil || row == nil {
		return
	}
	if u.Name != nil {
		row.Name = *u.Name
	}
	if u.Owner != nil {
		row.Owner = *u.Owner
	}
	if u.Audience != nil {
		row.Audience = *u.Audience
	}
	if u.AudienceNamedSetNull {
		row.AudienceNamed = nil
	} else if u.AudienceNamed != nil {
		row.AudienceNamed = *u.AudienceNamed
	}
	if u.AgentAccess != nil {
		row.AgentAccess = *u.AgentAccess
	}
	if u.EffectiveAudienceSetNull {
		row.EffectiveAudience = nil
	} else if u.EffectiveAudience != nil {
		row.EffectiveAudience = *u.EffectiveAudience
	}
	if u.EffectiveAgents != nil {
		row.EffectiveAgents = *u.EffectiveAgents
	}
}

// FolderFilterConditions are the filter's conditions for a query of
// the caller's own, each column qualified by its table: each value is
// appended to args, its placeholder numbered after those already there.
